-- Ordered sample parameters: [3]
-- r3 project: merged; Compatible row-level input block
-- r2 window: merged; Compatible row-level input block
-- r1 filter: boundary; Preserve window input scope or specialized lowering boundary
-- r0 sort: merged; Track output ordering without a new query block
select
  "r1"."c0" as "customer_id",
  "r1"."c1" as "order_id",
  "r1"."c2" as "order_date",
  cast("r1"."c3" as text) as "position"
from
  (
    select
      "orders"."customer_id" as "c0",
      "orders"."order_id" as "c1",
      "orders"."order_date" as "c2",
      row_number() over (
        partition by
          "orders"."customer_id"
        order by
          case
            when "orders"."order_date" is null then 1
            else 0
          end asc,
          "orders"."order_date" desc,
          "orders"."order_id" desc
      ) as "c3"
    from
      "orders"
  ) as "r1"
where
  ("r1"."c3" <= cast($1 as integer))
order by
  case
    when "r1"."c0" is null then 1
    else 0
  end asc,
  "r1"."c0" asc,
  "r1"."c3" asc;
